];

function getDepartamentoByDistance(lat, lon) {
  let masCercano = MAPA_DEPARTAMENTOS[0];
  let distMin = Infinity;
  for (const dep of MAPA_DEPARTAMENTOS) {
    const dist = Math.pow(lat - dep.lat, 2) + Math.pow(lon - dep.lon, 2);
    if (dist < distMin) {
      distMin = dist;
      masCercano = dep;
    }
  }
  return masCercano;
}

function getSemanaEpi(fechaStr) {
  const fecha = new Date(fechaStr);
  const target = new Date(fecha.valueOf());
  const dayNr = (fecha.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) {
    target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
  }
  const semana = 1 + Math.ceil((firstThursday - target) / 604800000);
  const anio = new Date(fecha.getFullYear(), 0, 4).getFullYear();
  return { anio, semana };
}

const ANIO_LIMITE = 2024;
const SEMANA_LIMITE = 52;

for (let itemIdx = 0; itemIdx < items.length; itemIdx++) {
  const item = items[itemIdx];
  const responses = Array.isArray(item.json) ? item.json : [item.json];

  for (let rIdx = 0; rIdx < responses.length; rIdx++) {
    const response = responses[rIdx];
    const data = response.daily;
    if (!data || !data.time) continue;

    // Identifica el departamento correcto según el item que responde n8n
    const index = responses.length > 1 ? rIdx : itemIdx;
    const dep = MAPA_DEPARTAMENTOS[index] || getDepartamentoByDistance(response.latitude, response.longitude);

    const grupos = {};

    for (let i = 0; i < data.time.length; i++) {
      const { anio, semana } = getSemanaEpi(data.time[i]);
      if (anio < 2010 || anio > ANIO_LIMITE || (anio === ANIO_LIMITE && semana > SEMANA_LIMITE)) {
        continue;
      }

      const key = `${anio}-${semana}`;
      if (!grupos[key]) {
        grupos[key] = {
          anio,
          semana,
          tmax: [], tmin: [], tmean: [], prec: [], hum: []
        };
      }

      if (data.temperature_2m_max?.[i] != null) grupos[key].tmax.push(data.temperature_2m_max[i]);
      if (data.temperature_2m_min?.[i] != null) grupos[key].tmin.push(data.temperature_2m_min[i]);
      if (data.temperature_2m_mean?.[i] != null) grupos[key].tmean.push(data.temperature_2m_mean[i]);
      if (data.precipitation_sum?.[i] != null) grupos[key].prec.push(data.precipitation_sum[i]);
      if (data.relative_humidity_2m_mean?.[i] != null) grupos[key].hum.push(data.relative_humidity_2m_mean[i]);
    }

    const promedio = arr => arr.length ? Number((arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1)) : 0;
    const suma = arr => arr.length ? Number((arr.reduce((a, b) => a + b, 0)).toFixed(1)) : 0;

    for (const key in grupos) {
      const g = grupos[key];
      const tmax = promedio(g.tmax);
      const tmin = promedio(g.tmin);
      const tmean = promedio(g.tmean);
      const prec = suma(g.prec);
      const hum = promedio(g.hum);

      const query = `
        INSERT INTO dato_climatico (
          id_departamento, id_periodo,
          temp_max_promedio, temp_min_promedio, temp_mean_promedio,
          precipitacion_total, humedad_promedio
        )
        SELECT
          '${dep.id}', pe.id_periodo,
          ${tmax}, ${tmin}, ${tmean}, ${prec}, ${hum}
        FROM periodo_epidemiologico pe
        WHERE pe.anio = ${g.anio} AND pe.semana = ${g.semana}
        ON CONFLICT (id_departamento, id_periodo) DO NOTHING
      `.trim();

      output.push({ json: { query, id_dep: dep.id, dep: dep.nombre, anio: g.anio, semana: g.semana } });
    }
  }
}

return output;
